query IssueByNumber($owner: String!, $repo: String!, $number: Int!) {
    repository(owner: $owner, name: $repo) {
      hasIssuesEnabled
      issue: issueOrPullRequest(number: $number) {
        __typename
        ...on Issue{number,state,title,id}
        ...on PullRequest{number,state,title,id}
      }
    }
  }
